PR #377: Per-tenant token-bucket rate limiting + upstream 429 handling

Tenants on the shared gateway can currently starve each other: one batch job at 400 rps pushed everyone else into upstream 429s on Tuesday.
This adds an in-process token bucket per tenant (limits from tenant config, default 20 rps / burst 40) and returns 429 with Retry-After when a tenant is over.
When the upstream itself returns 429 we retry once, honoring its Retry-After capped at 5s; any other upstream error is passed straight through.
Bucket state is bounded by an LRU (10k tenants), so idle tenants do not accumulate.
Rate-limit decisions are logged with a key fingerprint for debugging.

diff --git a/src/ratelimit/bucket.ts b/src/ratelimit/bucket.ts
new file mode 100644
index 0000000..f1e2d3c
--- /dev/null
+++ b/src/ratelimit/bucket.ts
@@ -0,0 +1,36 @@
+import { createHash } from "node:crypto";
+import { LRUCache } from "lru-cache";
+
+export type Limits = { ratePerSec: number; burst: number };
+type Bucket = { tokens: number; updatedMs: number };
+
+export class TenantLimiter {
+  private buckets = new LRUCache<string, Bucket>({ max: 10_000 });
+
+  constructor(private now: () => number = Date.now) {}
+
+  /** Returns 0 when admitted, otherwise milliseconds until a token is available. */
+  take(tenantId: string, limits: Limits): number {
+    const nowMs = this.now();
+    const b = this.buckets.get(tenantId) ?? { tokens: limits.burst, updatedMs: nowMs };
+    const elapsedSec = (nowMs - b.updatedMs) / 1000;
+    b.tokens = Math.min(limits.burst, b.tokens + elapsedSec * limits.ratePerSec);
+    b.updatedMs = nowMs;
+    if (b.tokens >= 1) {
+      b.tokens -= 1;
+      this.buckets.set(tenantId, b);
+      return 0;
+    }
+    this.buckets.set(tenantId, b);
+    return Math.ceil(((1 - b.tokens) / limits.ratePerSec) * 1000);
+  }
+}
+
+export function keyFingerprint(apiKey: string): string {
+  return createHash("sha256").update(apiKey).digest("hex").slice(0, 10);
+}
diff --git a/src/routes/completions.ts b/src/routes/completions.ts
index 8d2c4e1..3b7a9f0 100644
--- a/src/routes/completions.ts
+++ b/src/routes/completions.ts
@@ -1,22 +1,49 @@
 import type { FastifyInstance } from "fastify";
 import { authenticate } from "../auth";
 import { upstream } from "../upstream";
+import { TenantLimiter, keyFingerprint } from "../ratelimit/bucket";
+import { limitsFor } from "../tenants";
+
+const limiter = new TenantLimiter();
+const MAX_UPSTREAM_RETRY_MS = 5_000;
+
+function retryAfterMs(header: string | undefined): number {
+  const secs = Number(header);
+  if (!Number.isFinite(secs) || secs < 0) return 1_000;
+  return Math.min(secs * 1000, MAX_UPSTREAM_RETRY_MS);
+}

 export async function completionsRoutes(app: FastifyInstance) {
   app.post("/v1/chat/completions", async (req, reply) => {
     const tenant = await authenticate(req);
-    const res = await upstream.chat(req.body, { signal: req.signal });
+
+    const waitMs = limiter.take(tenant.id, limitsFor(tenant));
+    if (waitMs > 0) {
+      req.log.info(
+        { tenant: tenant.id, key: keyFingerprint(tenant.apiKey), waitMs },
+        "tenant rate limited",
+      );
+      return reply
+        .code(429)
+        .header("Retry-After", String(Math.ceil(waitMs / 1000)))
+        .send({ error: { type: "rate_limited", message: "tenant rate limit exceeded" } });
+    }
+
+    let res = await upstream.chat(req.body, { signal: req.signal });
+    if (res.status === 429) {
+      const delay = retryAfterMs(res.headers.get("retry-after") ?? undefined);
+      req.log.warn({ tenant: tenant.id, delay }, "upstream 429, retrying once");
+      await new Promise((r) => setTimeout(r, delay));
+      res = await upstream.chat(req.body, { signal: req.signal });
+    }
     return reply.code(res.status).headers(res.forwardHeaders()).send(res.body);
   });
 }
diff --git a/src/ratelimit/bucket.test.ts b/src/ratelimit/bucket.test.ts
new file mode 100644
index 0000000..77aa012
--- /dev/null
+++ b/src/ratelimit/bucket.test.ts
@@ -0,0 +1,18 @@
+import { expect, test } from "bun:test";
+import { TenantLimiter } from "./bucket";
+
+test("admits burst, then rate-limits, then refills", () => {
+  let t = 0;
+  const l = new TenantLimiter(() => t);
+  const lim = { ratePerSec: 2, burst: 3 };
+  expect([l.take("a", lim), l.take("a", lim), l.take("a", lim)]).toEqual([0, 0, 0]);
+  expect(l.take("a", lim)).toBe(500);
+  t = 500;
+  expect(l.take("a", lim)).toBe(0);
+});
+
+test("tenants are isolated", () => {
+  const l = new TenantLimiter(() => 0);
+  const lim = { ratePerSec: 1, burst: 1 };
+  expect([l.take("a", lim), l.take("b", lim)]).toEqual([0, 0]);
+});
